import { useEffect, useLayoutEffect, useRef, useState } from "react";

// Pair with the CSS from the CSS tab. Two absolutely positioned copies swap
// over a box the hidden sizer holds steady: the outgoing line exits up
// through a small blur while the incoming one rises in from below, so a
// swap costs one --think-swap, not two.
const DEFAULT_STATES = ["Setting up a workplace", "Running a command", "Browsing files"];

const ms = (name, fallback) => {
  const v = parseFloat(getComputedStyle(document.documentElement).getPropertyValue(name));
  return Number.isFinite(v) ? v : fallback;
};

export function ThinkingStates({ states = DEFAULT_STATES }) {
  const [current, setCurrent] = useState(0);
  const [leaving, setLeaving] = useState(null); // index of the exiting line
  const [entering, setEntering] = useState(false);
  const liveRef = useRef(null);

  // Hold, then swap to the next state.
  useEffect(() => {
    const hold = setTimeout(() => {
      setLeaving(current);
      setCurrent((i) => (i + 1) % states.length);
      setEntering(true);
    }, ms("--think-hold", 2000));
    return () => clearTimeout(hold);
  }, [current, states.length]);

  // Flush the enter-start rest pose before paint, release it after
  // --think-gap, and drop the outgoing copy once its swap has played.
  useLayoutEffect(() => {
    if (!entering) return;
    if (liveRef.current) void liveRef.current.offsetWidth;
    const gap = ms("--think-gap", 50);
    const swap = ms("--think-swap", 150);
    const release = setTimeout(() => setEntering(false), gap);
    const done = setTimeout(() => setLeaving(null), swap + gap);
    return () => { clearTimeout(release); clearTimeout(done); };
  }, [entering]);

  // The sizer holds the longest state so the box never resizes mid-swap.
  const longest = states.reduce((a, b) => (b.length > a.length ? b : a), "");

  return (
    <span className="t-think" role="status">
      <span className="t-think-sizer" aria-hidden="true">{longest}</span>
      {leaving !== null && (
        <span className="t-think-text is-exit" data-text={states[leaving]} aria-hidden="true">
          {states[leaving]}
        </span>
      )}
      <span
        key={current}
        ref={liveRef}
        className={"t-think-text" + (entering ? " is-enter-start" : "")}
        data-text={states[current]}
      >
        {states[current]}
      </span>
    </span>
  );
}

// Demo: what the preview renders. Edit freely.
export default function Demo() {
  return (
    <div className="demo">
      <ThinkingStates />
    </div>
  );
}

