import { useEffect, useRef } from "react";

// Pair with the CSS from the CSS tab. The transcript is rendered twice so the
// loop wraps without a visible jump; the scroll steps up --reason-lines
// lines every --reason-hold. Give .t-reason a height (it clips the copies).
const num = (name, fallback) => {
  const v = parseFloat(getComputedStyle(document.documentElement).getPropertyValue(name));
  return Number.isFinite(v) ? v : fallback;
};

export function ReasoningStream({ children, className = "" }) {
  const scrollRef = useRef(null);
  const textRef = useRef(null);

  useEffect(() => {
    const scroll = scrollRef.current;
    const text = textRef.current;
    if (!scroll || !text) return;
    let offset = 0;
    let timer;

    const step = () => {
      timer = setTimeout(() => {
        const lineH = parseFloat(getComputedStyle(text).lineHeight) || 18;
        const stepPx = lineH * num("--reason-lines", 2);
        const dur = num("--reason-step", 500);
        const ease =
          getComputedStyle(document.documentElement).getPropertyValue("--reason-ease").trim() ||
          "ease-out";
        offset += stepPx;
        scroll.style.transition = "transform " + dur + "ms " + ease;
        scroll.style.transform = "translateY(" + -offset + "px)";
        timer = setTimeout(() => {
          // Wrap by one copy's height; the clone underneath hides the jump.
          const copyH = text.offsetHeight;
          if (offset >= copyH) {
            offset -= copyH;
            scroll.style.transition = "none";
            scroll.style.transform = "translateY(" + -offset + "px)";
            void scroll.offsetWidth; // flush before the next tween
          }
          step();
        }, dur + 30);
      }, num("--reason-hold", 840));
    };

    step();
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className={"t-reason" + (className ? " " + className : "")}>
      <div className="t-reason-viewport">
        <div className="t-reason-scroll" ref={scrollRef}>
          <div className="t-reason-text" ref={textRef}>{children}</div>
          <div className="t-reason-text" aria-hidden="true">{children}</div>
        </div>
      </div>
    </div>
  );
}

// Demo: what the preview renders. Edit freely.
export default function Demo() {
  return (
    <div className="demo">
      <div style={{ width: 240 }}><ReasoningStream>Reading the component tree. Checking which states change. Comparing durations against the easing tokens. Drafting a smoother exit for the dropdown.</ReasoningStream></div>
    </div>
  );
}

