import { useEffect, useRef } from "react";

// Pair with the CSS from the CSS tab. Each word is a span that rests
// visible; a replay wipes them all with no transition, flushes one reflow,
// then resolves them in order through opacity plus a small blur, one
// every --stream-gap. Bump `replayKey` to stream the text again.
export function StreamingText({ text, replayKey = 0, autoplay = true }) {
  const words = text.trim().split(/\s+/);
  const spansRef = useRef([]);
  const timer = useRef(null);

  useEffect(() => {
    if (!autoplay && replayKey === 0) return;
    const spans = spansRef.current.filter(Boolean);
    if (!spans.length) return;
    clearTimeout(timer.current);

    // Snap back to nothing without animating the wipe itself.
    spans.forEach((s) => {
      s.style.transition = "none";
      s.classList.remove("is-in");
    });
    void spans[0].offsetWidth; // flush the wipe in the same task
    spans.forEach((s) => { s.style.transition = ""; });

    const gap =
      parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--stream-gap")) || 60;
    const next = (n) => {
      if (n >= spans.length) return;
      spans[n].classList.add("is-in");
      timer.current = setTimeout(() => next(n + 1), gap);
    };
    next(0);
    return () => clearTimeout(timer.current);
  }, [text, replayKey, autoplay]);

  return (
    <div className="t-stream">
      {words.map((w, i) => (
        <span
          key={i}
          ref={(el) => { spansRef.current[i] = el; }}
          className="t-stream-w is-in"
        >
          {w}
          {i < words.length - 1 ? " " : ""}
        </span>
      ))}
    </div>
  );
}

// Demo: what the preview renders. Edit freely.
export default function Demo() {
  return (
    <div className="demo">
      <div style={{ width: 240 }}><StreamingText text="Motion should explain what changed, never make you wait for it." /></div>
    </div>
  );
}

