import { useLayoutEffect, useRef, useState } from "react";

// Pair with the CSS from the CSS tab. Sonner-style stacking: a new banner
// enters at depth 0 while everything already stacked steps one depth back;
// a fourth arrival sends the oldest out. Hover spread is geometry on the
// wrapper, not :hover, because the gaps between spread banners belong to
// no element.
//
// Usage: keep the queue in the parent and push { id, node } entries.
//   const [banners, setBanners] = useState([]);
//   setBanners((b) => [...b, { id: Date.now(), node: <YourBanner /> }]);
//   <BannerStack banners={banners} />
const ms = (name, fallback) => {
  const v = parseFloat(getComputedStyle(document.documentElement).getPropertyValue(name));
  return Number.isFinite(v) ? v : fallback;
};

export function BannerStack({ banners, className = "" }) {
  const [items, setItems] = useState([]); // newest first
  const [spread, setSpread] = useState(false);
  const stackRef = useRef(null);
  const seen = useRef(new Set());

  // Adopt the newest banner: depth 0 with the pre-open pose, older ones
  // step back, anything past depth 2 starts leaving.
  useLayoutEffect(() => {
    const latest = banners[banners.length - 1];
    if (!latest || seen.current.has(latest.id)) return;
    seen.current.add(latest.id);
    setItems((prev) => [
      { ...latest, depth: 0, enter: true, leaving: false },
      ...prev.map((b, i) =>
        i + 1 > 2 ? { ...b, leaving: true } : { ...b, depth: i + 1 }
      ),
    ]);
  }, [banners]);

  // Flush the pre-open rest state before paint, then release it in the
  // same task; drop banners that have left after --stack-close.
  useLayoutEffect(() => {
    const entering = items.find((b) => b.enter);
    if (entering && stackRef.current) {
      const el = stackRef.current.querySelector('[data-id="' + entering.id + '"]');
      if (el) void el.offsetWidth;
      setItems((prev) => prev.map((b) => (b.enter ? { ...b, enter: false } : b)));
    }
    if (items.some((b) => b.leaving)) {
      const t = setTimeout(
        () => setItems((prev) => prev.filter((b) => !b.leaving)),
        ms("--stack-close", 250) + 60
      );
      return () => clearTimeout(t);
    }
  }, [items]);

  const within = (e, above) => {
    const r = stackRef.current.getBoundingClientRect();
    return (
      e.clientX >= r.left && e.clientX <= r.right &&
      e.clientY <= r.bottom && e.clientY >= r.top - above
    );
  };
  const onPointerMove = (e) => {
    const stack = stackRef.current;
    if (!stack) return;
    const spreadHeight = (stack.offsetHeight + ms("--stack-spread-gap", 8)) * 2;
    if (spread) {
      if (!within(e, spreadHeight)) setSpread(false);
    } else if (within(e, 0)) {
      setSpread(true);
    }
  };

  return (
    <div
      className={"t-stack-stage" + (className ? " " + className : "")}
      onPointerMove={onPointerMove}
      onPointerLeave={() => setSpread(false)}
    >
      <div ref={stackRef} className={"t-stack" + (spread ? " is-spread" : "")}>
        {items.map((b) => (
          <div
            key={b.id}
            data-id={b.id}
            data-depth={b.depth}
            className={
              "t-stack-banner" +
              (b.enter ? " is-enter" : "") +
              (b.leaving ? " is-leaving" : "")
            }
          >
            {b.node}
          </div>
        ))}
      </div>
    </div>
  );
}

// Demo: what the preview renders. Edit freely.
function StackDemo() {
  const [banners, setBanners] = useState([]);
  const add = () => {
    const n = banners.length + 1;
    setBanners((b) => [...b, { id: String(n), node: <div className="demo-surface">Notification {n}</div> }]);
  };
  return (
    <>
      <BannerStack banners={banners} />
      <button type="button" onClick={add}>Add banner</button>
    </>
  );
}

export default function Demo() {
  return (
    <div className="demo">
      <StackDemo />
    </div>
  );
}

css:
:root {
  --stack-open: 350ms;
  --stack-close: 250ms;
  --stack-rise: 60px;
  --stack-blur: 2px;
  --stack-scale: 0.97;
  --stack-peek: 12px;
  --stack-spread-gap: 8px;
  --stack-depth-scale: 0.06;
  --stack-depth-fade: 0.4;
  --stack-depth1-blur: 1px;
  --stack-depth2-blur: 2px;
  --stack-ease: cubic-bezier(0.22, 1, 0.36, 1);
}

.t-stack { position: relative; }
.t-stack-banner {
  position: absolute;
  left: 0;
  bottom: 0;
  /* Centre origin so an arriving banner scales like a toast; the
     push-back depths switch to the bottom edge, which they can do
     freely because the swap happens at identity. */
  transform-origin: 50% 50%;
  /* Explicit blur(0) rather than an unset filter — blur → none is
     not reliably interpolated, and the cross-blur would snap. */
  filter: blur(0);
  will-change: transform, opacity, filter;
  transition:
    transform var(--stack-open) var(--stack-ease),
    opacity var(--stack-open) var(--stack-ease),
    filter var(--stack-open) var(--stack-ease);
}
.t-stack-banner[data-depth="0"] {
  z-index: 3;
  transform: translateY(0) scale(1);
  opacity: 1;
}
.t-stack-banner[data-depth="1"] {
  z-index: 2;
  transform-origin: 50% 100%;
  transform: translateY(calc(var(--stack-peek) * -1))
             scale(calc(1 - var(--stack-depth-scale)));
  opacity: calc(1 - var(--stack-depth-fade));
  filter: blur(var(--stack-depth1-blur));
}
.t-stack-banner[data-depth="2"] {
  z-index: 1;
  transform-origin: 50% 100%;
  transform: translateY(calc(var(--stack-peek) * -2))
             scale(calc(1 - var(--stack-depth-scale) * 2));
  opacity: calc(1 - var(--stack-depth-fade) * 1.6);
  filter: blur(var(--stack-depth2-blur));
}
/* Spread: newest stays put, older ones climb one banner height
   each (100% = the banner's own height). Driven by a class, not
   :hover — the gaps between spread banners belong to no element. */
.t-stack.is-spread .t-stack-banner[data-depth="1"],
.t-stack.is-spread .t-stack-banner[data-depth="2"] { opacity: 1; filter: blur(0); }
.t-stack.is-spread .t-stack-banner[data-depth="1"] {
  transform: translateY(calc((100% + var(--stack-spread-gap)) * -1)) scale(1);
}
.t-stack.is-spread .t-stack-banner[data-depth="2"] {
  transform: translateY(calc((100% + var(--stack-spread-gap)) * -2)) scale(1);
}
.t-stack-banner.is-enter {
  transition: none;
  transform: translateY(var(--stack-rise)) scale(var(--stack-scale));
  opacity: 0;
  filter: blur(var(--stack-blur));
}
.t-stack-banner.is-leaving {
  z-index: 0;
  transform-origin: 50% 100%;
  transform: translateY(calc(var(--stack-peek) * -3))
             scale(calc(1 - var(--stack-depth-scale) * 3));
  opacity: 0;
  filter: blur(var(--stack-blur));
  transition:
    transform var(--stack-close) var(--stack-ease),
    opacity var(--stack-close) var(--stack-ease),
    filter var(--stack-close) var(--stack-ease);
}

@media (prefers-reduced-motion: reduce) {
  .t-stack-banner { transition: none !important; transform: none !important; filter: none !important; }
}

/* Demo scaffolding (not part of the transition) */
.demo { display: flex; flex-direction: column; align-items: center; gap: 16px; }
.demo button:not([class]), .demo-btn {
  padding: 8px 14px;
  border: 0;
  border-radius: 999px;
  background: var(--stage-surface);
  color: var(--stage-fg);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08), inset 0 0 0 1px var(--stage-border);
  font: inherit;
  font-weight: 500;
  cursor: pointer;
}
.demo-surface {
  padding: 14px 16px;
  border-radius: 14px;
  background: var(--stage-surface);
  color: var(--stage-fg);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06), inset 0 0 0 1px var(--stage-border);
}
.demo-muted { color: var(--stage-muted); font-size: 13px; }
/* Zero-specificity defaults: any rule in the transition's CSS wins. */
:where(.demo) :where(button) {
  padding: 7px 12px;
  border: 0;
  border-radius: 999px;
  background: var(--stage-surface);
  color: var(--stage-fg);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08), inset 0 0 0 1px var(--stage-border);
  font: inherit;
  font-weight: 500;
  cursor: pointer;
}
:where(.demo) :where(input[type="text"], input:not([type])) {
  width: 200px;
  padding: 9px 12px;
  border: 0;
  border-radius: 10px;
  background: var(--stage-surface);
  color: var(--stage-fg);
  box-shadow: inset 0 0 0 1px var(--stage-border);
  font: inherit;
  outline: none;
}
